"""Read ids.txt and print the next order id."""

import os


def base36_encode(n: int, width: int = 4) -> str:
    """Encode an integer as a zero-padded base-36 string of given width."""
    digits = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    result = []
    for _ in range(width):
        n, remainder = divmod(n, 36)
        result.append(digits[remainder])
    return "".join(reversed(result))


def base36_decode(s: str) -> int:
    """Decode a base-36 string to an integer."""
    return int(s, 36)


def next_id(last_id: str) -> str:
    """Given an id like 'ORD-243G', return the next id like 'ORD-243H'."""
    prefix, suffix = last_id.rsplit("-", 1)
    n = base36_decode(suffix)
    return f"{prefix}-{base36_encode(n + 1)}"


def main() -> None:
    ids_file = os.path.join(os.getcwd(), "ids.txt")
    last_id = None
    with open(ids_file) as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            # Lines have format: <number>\t<order-id>
            parts = line.split("\t")
            if len(parts) == 2:
                candidate = parts[1].strip()
            else:
                candidate = parts[0].strip()
            if candidate.startswith("ORD-"):
                last_id = candidate
    if last_id is None:
        # No ids yet; start from the beginning
        print("ORD-0000")
    else:
        print(next_id(last_id))


if __name__ == "__main__":
    main()

