"""Print the next order id to stdout."""
import sys

_ALPHABET = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"


def _to_base36(n: int) -> str:
    """Convert a non-negative integer to a base-36 string."""
    if n == 0:
        return "0"
    result = []
    while n:
        result.append(_ALPHABET[n % 36])
        n //= 36
    return "".join(reversed(result))


def main() -> None:
    try:
        with open("ids.txt", encoding="utf-8") as f:
            lines = [line.strip() for line in f if line.strip()]
    except FileNotFoundError:
        lines = []

    if not lines:
        next_id = "ORD-0000"
    else:
        last_id = lines[-1]
        if not last_id.startswith("ORD-") or len(last_id) != 8:
            print(f"error: unexpected id format: {last_id!r}", file=sys.stderr)
            sys.exit(1)

        suffix = last_id[4:]
        num = int(suffix, 36) + 1
        next_suffix = _to_base36(num).zfill(4).upper()
        next_id = f"ORD-{next_suffix}"

    sys.stdout.write(next_id + "\n")


if __name__ == "__main__":
    main()

