"""dedupe.py — remove duplicate events sharing an event_id.

Reads events.jsonl from the current directory, deduplicates by event_id
keeping the earliest reported_at (first-write-wins), and writes the
result to deduped.jsonl.
"""

import json
from datetime import datetime


def main() -> None:
    seen: dict[str, dict] = {}

    with open("events.jsonl") as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            record = json.loads(line)
            eid = record["event_id"]
            ts = datetime.fromisoformat(record["reported_at"])

            if eid not in seen or ts < seen[eid]["_ts"]:
                seen[eid] = {**record, "_ts": ts}

    with open("deduped.jsonl", "w") as out:
        for record in seen.values():
            # Drop the internal _ts key before writing
            clean = {k: v for k, v in record.items() if k != "_ts"}
            out.write(json.dumps(clean, ensure_ascii=False) + "\n")


if __name__ == "__main__":
    main()

