#!/usr/bin/env python3
"""Generate manifest.json with SHA-256 digests for all files under release/."""

import hashlib
import json
from pathlib import Path

RELEASE_DIR = Path(__file__).resolve().parent / "release"
MANIFEST_PATH = Path(__file__).resolve().parent / "manifest.json"


def file_digest(path: Path) -> str:
    """Return the SHA-256 hex digest of a file."""
    h = hashlib.sha256()
    with open(path, "rb") as f:
        for chunk in iter(lambda: f.read(65536), b""):
            h.update(chunk)
    return h.hexdigest()


def main() -> None:
    if not RELEASE_DIR.is_dir():
        print(f"Error: {RELEASE_DIR} does not exist.")
        return

    manifest = {}
    for path in sorted(RELEASE_DIR.rglob("*")):
        if path.is_file():
            rel_path = path.relative_to(RELEASE_DIR).as_posix()
            manifest[rel_path] = file_digest(path)

    with open(MANIFEST_PATH, "w") as f:
        json.dump(manifest, f, indent=2)
        f.write("\n")

    print(f"Wrote manifest.json with {len(manifest)} entries.")


if __name__ == "__main__":
    main()

