"""
Usage: python rotate.py AS_OF

AS_OF is a Unix timestamp in integer seconds, UTC.

Reads app.log, moves every entry strictly older than 7 days before AS_OF
to archive.log (appending, preserving order), and rewrites app.log with
the remaining entries in their original order.
"""

import sys
from datetime import datetime, timezone, timedelta


def parse_timestamp(line: str) -> datetime | None:
    """Parse 'YYYY-MM-DD HH:MM:SS' from the start of a line, treating it as UTC."""
    if len(line) < 19:
        return None
    try:
        return datetime.strptime(line[:19], "%Y-%m-%d %H:%M:%S").replace(tzinfo=timezone.utc)
    except ValueError:
        return None


def main() -> None:
    if len(sys.argv) != 2:
        print("Usage: python rotate.py AS_OF", file=sys.stderr)
        sys.exit(1)

    try:
        as_of = int(sys.argv[1])
    except ValueError:
        print("AS_OF must be an integer Unix timestamp in seconds.", file=sys.stderr)
        sys.exit(1)

    cutoff = datetime.fromtimestamp(as_of, tz=timezone.utc) - timedelta(days=7)

    try:
        with open("app.log", "r") as f:
            lines = f.readlines()
    except FileNotFoundError:
        print("app.log not found.", file=sys.stderr)
        sys.exit(1)

    keep: list[str] = []
    archive: list[str] = []

    for line in lines:
        # Preserve empty lines as they are, but they have no timestamp so keep them.
        if not line.strip():
            keep.append(line)
            continue

        ts = parse_timestamp(line)
        if ts is None:
            # Line doesn't start with a valid timestamp — keep it in app.log
            keep.append(line)
        elif ts < cutoff:
            archive.append(line)
        else:
            keep.append(line)

    # Append to archive.log
    if archive:
        try:
            with open("archive.log", "a") as f:
                f.writelines(archive)
        except FileNotFoundError:
            with open("archive.log", "w") as f:
                f.writelines(archive)

    # Rewrite app.log
    with open("app.log", "w") as f:
        f.writelines(keep)


if __name__ == "__main__":
    main()

