Usage: python rotate.py AS_OF

AS_OF is a Unix timestamp in integer seconds. Every entry in app.log
whose timestamp is strictly older than 7 days before AS_OF is moved
to archive.log (appended, preserving order), and app.log is rewritten
with the remaining entries.
"""

import sys
from datetime import datetime, timezone

LOG_FILE = "app.log"
ARCHIVE_FILE = "archive.log"
SECONDS_IN_7_DAYS = 7 * 24 * 60 * 60


def parse_timestamp(line: str) -> datetime | None:
    """Parse 'YYYY-MM-DD HH:MM:SS' from the start of a line."""
    try:
        return datetime.strptime(line[:19], "%Y-%m-%d %H:%M:%S").replace(
            tzinfo=timezone.utc
        )
    except (ValueError, IndexError):
        return None


def main() -> None:
    if len(sys.argv) != 2:
        print("Usage: python rotate.py AS_OF", file=sys.stderr)
        sys.exit(1)

    try:
        as_of = int(sys.argv[1])
    except ValueError:
        print("Error: AS_OF must be an integer Unix timestamp", file=sys.stderr)
        sys.exit(1)

    as_of_dt = datetime.fromtimestamp(as_of, tz=timezone.utc)
    cutoff_dt = as_of_dt.timestamp() - SECONDS_IN_7_DAYS
    cutoff_dt_obj = datetime.fromtimestamp(cutoff_dt, tz=timezone.utc)

    try:
        with open(LOG_FILE) as f:
            lines = f.readlines()
    except FileNotFoundError:
        print("Error: app.log not found", file=sys.stderr)
        sys.exit(1)

    keep_lines: list[str] = []
    archive_lines: list[str] = []

    for line in lines:
        if not line.strip():
            continue
        ts = parse_timestamp(line)
        if ts is None:
            # Lines without a valid timestamp stay in app.log
            keep_lines.append(line)
        elif ts < cutoff_dt_obj:
            archive_lines.append(line)
        else:
            keep_lines.append(line)

    with open(LOG_FILE, "w") as f:
        f.writelines(keep_lines)

    if archive_lines:
        with open(ARCHIVE_FILE, "a") as f:
            f.writelines(archive_lines)


if __name__ == "__main__":
    main()

